package dev.aster.vega.expression

import dev.aster.vega.model.DiagnosticCodes
import dev.aster.vega.model.VegaDiagnostic
import dev.aster.vega.model.VegaValue
import dev.aster.vega.model.asString
import dev.aster.vega.model.field

/**
 * Expression API surface.
 *
 * Milestone 0 fixes the contracts; the lexer, parser and evaluator arrive with the dataflow in
 * Milestone 4 (PROJECT_BRIEF.md 20). Two rules are load-bearing and encoded here rather than left
 * to the implementation:
 * - no `eval`, JavaScript, reflection-based dispatch or generated bytecode (PROJECT_BRIEF.md 6.1)
 * - an unknown function is a diagnostic, never a silent `null`
 */
public interface Expression {
  /** The original source text, kept for diagnostics and debugging. */
  public val source: String

  /** Signal names this expression reads, so the dataflow knows what to invalidate. */
  public val signalDependencies: Set<String>

  /** Datum field paths this expression reads. */
  public val fieldDependencies: Set<String>

  /**
   * Datasets this expression names outright: the string literal a `data()` or `indata()` is given.
   *
   * Upstream's `dataVisitor` reads the same argument at parse time and turns it into a parameter of
   * the operator the expression belongs to, which is what puts the dataset ahead of it in the
   * dataflow's ranking. Naming them here buys the same ordering, so a scale domain or a transform
   * parameter written as an expression can be resolved after the datasets it reads.
   */
  public val dataDependencies: Set<String>

  /**
   * True when a dataset is named by an expression rather than a literal, as in `data(chosen)`.
   *
   * There is no name to record, so anything ordering itself against this expression has to wait for
   * *every* dataset. Upstream refuses the case outright — "First argument to data functions must be
   * a string literal" — and this engine evaluates it instead, so the ordering has to cover it.
   */
  public val readsUnnamedDataset: Boolean

  /**
   * Scales this expression names outright, through `scale`, `invert`, `domain`, `range` or
   * `bandwidth`.
   *
   * The counterpart of [dataDependencies] for upstream's `scaleVisitor`, and the reason a signal
   * reading `domain('xscale')` can be resolved once that one scale exists rather than not at all.
   */
  public val scaleDependencies: Set<String>

  /**
   * True when a scale is named by an expression rather than a literal, as in `scale(which, v)`.
   *
   * Upstream's `scaleVisitor` makes *every* scale in the enclosing scope a dependency in this case,
   * because there is no way to tell which one will be asked for.
   */
  public val readsUnnamedScale: Boolean

  /**
   * Datasets this expression *replaces*, through `setdata`.
   *
   * The mirror of [dataDependencies]: anything reading one of these has to be ordered behind the
   * expression rather than in front of it.
   */
  public val writtenDatasets: Set<String>

  /**
   * Functions this expression **calls**, by the name written at the call site.
   *
   * Every other dependency set here answers "what has to exist before this runs". This one answers
   * a different question — "was this capability asked for at all" — and it exists because a
   * capability a specification asks for and a host has not supplied is exactly the kind of thing
   * this engine reports rather than answers with a shrug. `containerSize()` is the case that
   * prompted it: it returns `[null, null]` outside a browser, which is upstream's own answer, so a
   * specification branching on a breakpoint silently takes the "no container" arm until a host says
   * how much room there is.
   *
   * Only a name written as an identifier in call position counts. That is the whole grammar — there
   * is no `eval` in a Vega expression, so a function cannot be reached any other way.
   */
  public val functionDependencies: Set<String>

  public fun evaluate(scope: ExpressionScope): VegaValue
}

/** Everything an expression can read. Passed explicitly; there is no ambient global scope. */
public interface ExpressionScope {
  /** The current datum, or [VegaValue.Null] outside a mark encoding. */
  public val datum: VegaValue

  public fun signal(name: String): VegaValue

  /** Named datasets, for `data('name')`. */
  public fun dataset(name: String): List<VegaValue>

  /**
   * `indata('name', 'field', value)` — how many rows of the named dataset carry that value.
   *
   * Not a boolean, despite the documentation: upstream returns the **count** of matching rows, or
   * `undefined` when there are none, and a specification that prints the result prints a number.
   * [VegaValue.Null] stands in for that `undefined`; both are falsey, so the usual
   * `if(indata(...))` reads the same either way.
   *
   * The default scans, which is correct and quadratic when called once per datum. A scope that
   * answers many of these — a mark encoding, in practice — should override with an index.
   */
  public fun indata(name: String, field: String, value: VegaValue): VegaValue =
    indataLookup(indataCounts(dataset(name), field), value)

  /**
   * `scale('name', value)` — a scale applied from inside an expression.
   *
   * Values in and values out, so `vega-expression` stays free of any scale type. A scope with no
   * scales returns null, which is what a bare expression evaluated outside a chart should do.
   */
  public fun applyScale(name: String, value: VegaValue): VegaValue = VegaValue.Null

  /** `invert('name', value)` — the same in reverse, for a continuous scale. */
  public fun invertScale(name: String, value: VegaValue): VegaValue = VegaValue.Null

  /** `domain('name')` — the scale's input extent, which a specification reads to size something. */
  public fun scaleDomain(name: String): VegaValue = VegaValue.Null

  /** `range('name')` — the scale's output extent. */
  public fun scaleRange(name: String): VegaValue = VegaValue.Null

  /**
   * `geoCentroid('projection', feature)` — where a shape balances, in projected coordinates.
   *
   * Declared here and implemented where projections live, exactly as `scale()` is: this module
   * knows nothing about geography and should not start. A scope with no projections answers null,
   * which is what a bare expression evaluated outside a chart should do.
   */
  public fun geoCentroid(projection: String?, geojson: VegaValue): VegaValue = VegaValue.Null

  /** `geoArea('projection', feature)` — how much of the page the shape covers. */
  public fun geoArea(projection: String?, geojson: VegaValue): VegaValue = VegaValue.Null

  /** `geoBounds(projection, feature)` — the box a feature occupies once drawn. */
  public fun geoBounds(projection: String?, geojson: VegaValue): VegaValue = VegaValue.Null

  /**
   * `geoScale(projection)` — the projection's own scale, which a fitted one only knows once fitted.
   */
  public fun geoScale(projection: String?): VegaValue = VegaValue.Null

  /**
   * `gradient(scale, p0, p1[, count])` — a colour scale as a gradient a mark can be filled with.
   *
   * Answers the same object a specification can write by hand — `{"gradient": "linear", "x1": …,
   * "stops": [{"offset": …, "color": …}]}` — because that is what upstream's `Gradient` is: a plain
   * object its renderer turns into an SVG definition. So the value is usable wherever a literal one
   * is, and the encoder does not need to know which of the two it got.
   */
  public fun gradient(
    scale: String,
    from: VegaValue,
    to: VegaValue,
    count: VegaValue,
  ): VegaValue = VegaValue.Null

  /**
   * `geoShape(projection, feature)` — the feature drawn through the projection, as a path.
   *
   * The same stated divergence as `pathShape`, for the same reason: upstream returns a closure no
   * channel can consume — probed on a `symbol`, on a `path` mark and on a `shape` mark, and all
   * three throw — so the string that closure produces given no drawing context is what this
   * returns. The `geoshape` **transform** is the route that does work upstream, and it is
   * implemented and differentially verified; this is the same outline through the same machinery,
   * asked for one feature rather than a column of them.
   */
  public fun geoShape(projection: String?, geojson: VegaValue): VegaValue = VegaValue.Null

  /**
   * `warn(...)`, `info(...)` and `debug(...)` — a message from inside an expression.
   *
   * Every one of them **returns its last argument**, which is what lets a specification wrap a
   * value in one without changing what it computes. The message needs somewhere to go, and a scope
   * that has a diagnostic collector sends it there; the default drops it, which is what a bare
   * expression evaluated outside a chart can do — upstream in the same position throws on the
   * missing dataflow and swallows the error.
   */
  public fun log(level: String, message: String) {}

  /** `bandwidth('name')` — a band scale's band width, or zero for a scale that has none. */
  public fun scaleBandwidth(name: String): VegaValue = VegaValue.Num(0.0)

  /**
   * `setdata('name', rows)` — replaces a dataset's contents outright.
   *
   * The one expression function that *writes*. Upstream pulses a changeset that removes everything
   * and inserts the new rows, and returns 1. A scope with nowhere to put them ignores it, which is
   * what a bare expression evaluated outside a chart should do.
   */
  public fun setDataset(name: String, rows: List<VegaValue>) {}

  /**
   * `modify(name, insert, remove, toggle)` — rows added to or taken out of a dataset.
   *
   * Returns 1 when something was changed and **0 when there was nothing to do**, which is
   * upstream's own early exit: an empty dataset with nothing to insert or toggle is left alone and
   * says so.
   */
  public fun modifyDataset(
    name: String,
    insert: VegaValue,
    remove: VegaValue,
    toggle: VegaValue,
  ): Double = 0.0

  /**
   * `encode(item, set)` — re-encodes one scene item through a named encode block of its own mark.
   *
   * A side effect on a live view. A compiled scene has no items to re-encode, so the default does
   * nothing; the value the function returns is decided by the caller either way, which is why this
   * returns nothing.
   */
  public fun encodeItem(item: VegaValue, set: String) {}

  /**
   * `item()` — the scene item the event being handled landed on.
   *
   * One of upstream's five *event* functions, which read the event rather than the data: they are
   * generated as `event.vega.<name>` and so answer only while an event is being handled. Empty when
   * none is, which is upstream's `item || {}` and is why `encode(item(), 'select')` is a no-op
   * outside a handler rather than an error.
   */
  public fun activeItem(): VegaValue = VegaValue.EmptyObject

  /**
   * `xy()` — the event's position in the **root frame's** own coordinates, as a two-element array.
   *
   * Not the same as `event.x`: that is the raw pointer position as the platform reported it, where
   * this has the chart's padding and autosize origin taken off, so it is in the space marks are
   * placed in. `x()` and `y()` are its two components. [VegaValue.Null] when no event is being
   * handled.
   */
  public fun eventPoint(): VegaValue = VegaValue.Null

  /**
   * `inScope(item)` — whether the item is inside the group this expression belongs to.
   *
   * False with no enclosing group, which is what upstream answers when its `context.group` is unset
   * — including for every expression in a top-level signal, where `inScope(anything)` is false
   * there too.
   */
  public fun inScope(item: VegaValue): Boolean = false

  /**
   * `intersect([[x0, y0], [x1, y1]][, opt])` — the scene items a box covers.
   *
   * An empty array where there is no scenegraph to ask, which is upstream's answer in the same
   * position: a signal is resolved before the scene exists, so `intersect` over a chart full of
   * marks answers `[]` there as well. A scope that *has* a scene — an event handler's — overrides
   * this.
   */
  public fun intersect(box: VegaValue, options: VegaValue): VegaValue = VegaValue.Arr(emptyList())

  /** `intersectLasso(mark, points, unit)` — the same question asked with a freehand outline. */
  public fun intersectLasso(mark: String, points: VegaValue, unit: VegaValue): VegaValue =
    VegaValue.Arr(emptyList())

  /**
   * `treePath('name', from, to)` — the rows between two nodes of a stratified dataset.
   *
   * A scope with no tree of that name returns null, which is what upstream returns for a link whose
   * ends are not both in the tree.
   */
  public fun treePath(name: String, from: VegaValue, to: VegaValue): VegaValue = VegaValue.Null

  /** `treeAncestors('name', node)` — that node's row and every ancestor's, the root last. */
  public fun treeAncestors(name: String, node: VegaValue): VegaValue = VegaValue.Null

  /**
   * The stream `random()` and the `sample*` family draw from.
   *
   * On the scope rather than in [Functions] because it is the one family whose answer depends on
   * how many times it has already been asked, and per-evaluation state is what a scope is for.
   * Upstream shares one module-level generator across a whole view, so a chart's picture depends on
   * the order its expressions run in as much as on the generator; handing out a fresh stream per
   * call would be reproducible and would not be upstream.
   */
  public val random: RandomStream
    get() = DetachedStream

  /** `now()` — the instant this compile is pinned to; see [Clock]. */
  public fun now(): Double = Clock.PINNED
}

/**
 * The stream a scope that is not compiling a chart draws from.
 *
 * Shared, and so *not* reproducible across evaluations — which is the point: it exists for a bare
 * expression evaluated in a test, where nothing downstream depends on the sequence. Every scope the
 * runtime builds owns a stream of its own, seeded per compile.
 */
private val DetachedStream = RandomStream()

/**
 * The index upstream's `indata` looks a value up in: string-coerced field value to row count.
 *
 * Upstream builds it with an `aggregate` grouped by the field feeding a `TupleIndex`, whose map is
 * a plain JavaScript object — so the key is the field value **coerced to a string**, and so is the
 * value looked up. That is the whole comparison, and it is not `===`: `indata('t', 'k', 1)` finds a
 * row whose `k` is the string `"1"`, and `indata('t', 'k', true)` finds one whose `k` is `"true"`.
 * Reading the documentation's "matches value" as strict equality gives a chart that is silently
 * missing exactly the rows whose types were not what the specification's author assumed.
 */
public fun indataCounts(rows: List<VegaValue>, field: String): Map<String, Int> =
  rows.groupingBy { it.field(field).asString() }.eachCount()

/** Reads [indataCounts] the way upstream does: the count, or absent rather than zero. */
public fun indataLookup(counts: Map<String, Int>, value: VegaValue): VegaValue =
  counts[value.asString()]?.let { VegaValue.Num(it.toDouble()) } ?: VegaValue.Null

public sealed interface ExpressionResult {
  public data class Compiled(val expression: Expression) : ExpressionResult

  public data class Failed(val diagnostic: VegaDiagnostic) : ExpressionResult
}

/**
 * Parses and caches expressions.
 *
 * Implementations must be free of global mutable state: a compiler instance belongs to one runtime,
 * so clearing or discarding it is always possible.
 */
public interface ExpressionCompiler {
  public fun compile(source: String): ExpressionResult
}

/**
 * Bounded LRU cache in front of an [ExpressionCompiler].
 *
 * Vega specifications reuse the same expression strings across many marks and updates, so caching
 * by source text avoids reparsing. Owned by its creator rather than being a singleton, so its
 * lifetime is controllable (PROJECT_BRIEF.md 21).
 */
public class CachingExpressionCompiler(
  private val delegate: ExpressionCompiler,
  private val maxEntries: Int = 512,
) : ExpressionCompiler {

  // Insertion-ordered, with a hit moved back to the young end by hand — `LinkedHashMap`'s
  // access-order mode is a JVM-only facility, and this is the same policy in three lines. See
  // `TextLayoutCache`, which caches layouts the same way for the same reason.
  private val cache = LinkedHashMap<String, ExpressionResult>()

  public val size: Int
    get() = cache.size

  override fun compile(source: String): ExpressionResult {
    cache.remove(source)?.let { hit ->
      cache[source] = hit
      return hit
    }
    return compiled(source)
  }

  private fun compiled(source: String): ExpressionResult {
    val result = cache.getOrPut(source) { delegate.compile(source) }
    // Insertion order puts the least recently used first, which is the one to drop.
    if (cache.size > maxEntries) cache.remove(cache.keys.first())
    return result
  }

  public fun clear() {
    cache.clear()
  }
}

/**
 * A compiler that refuses everything, for a caller that has to hand one over and evaluates nothing.
 *
 * What is left of the placeholder that stood in before there was an expression engine: it said
 * "planned for Milestone 4", which stopped being true a long time ago and would have been a
 * puzzling thing for a chart to report. It refuses with a **structured diagnostic** rather than a
 * null, which is the part worth keeping — PROJECT_BRIEF.md 3.3, never silently ignore what you
 * cannot do.
 */
public class RefusingExpressionCompiler : ExpressionCompiler {
  override fun compile(source: String): ExpressionResult =
    ExpressionResult.Failed(
      VegaDiagnostic(
        severity = dev.aster.vega.model.DiagnosticSeverity.ERROR,
        code = DiagnosticCodes.EXPRESSION_UNSUPPORTED_FUNCTION,
        message = "This compiler evaluates no expressions; '$source' was refused",
      )
    )
}
